const caseKey=new URLSearchParams(location.search).get('project')||'jala';
const project=window.CASES[caseKey];
const main=document.querySelector('#case-main');
const reduceMotion=matchMedia('(prefers-reduced-motion:reduce)');
if(!project){main.innerHTML='<section class="story-section section-shell"><h1>这一页还没写到。</h1><a class="primary-button" href="contents.html">回到作品目录 ↗</a></section>';}else{
 document.title=`${project.title} · Sherry 燕骁然`;
 document.querySelector('meta[name="description"]').content=project.intro;
 const ids=Object.keys(window.CASES),nextKey=ids[(ids.indexOf(caseKey)+1)%ids.length];
 main.innerHTML=`<section class="case-hero story-section section-shell" id="overview"><div class="case-hero-copy"><span class="eyebrow">${project.category} / CASE STUDY</span><span class="handwritten case-hello">打开这个故事 ↙</span><h1>${project.title}</h1><p class="case-subtitle">${project.subtitle}</p><p class="case-intro">${project.intro}</p><div class="case-role"><small>我的工作</small>${project.role}</div><a class="inline-link" href="#chapter-1">从背景开始读 ↓</a></div>${caseKey==='jala'?`<div class="case-cover jala"><figure><span class="tape"></span><div class="jala-native"><small>GROW TOGETHER / JALA</small><strong>一起<br><em>玩到“伽”</em></strong><div><span>01 创建角色</span><span>02 点技能树</span><span>03 打怪升级</span><span>04 游戏大佬</span></div><b>✦ CAREER ADVENTURE</b></div><figcaption class="handwritten">每一段成长，都有人同行。</figcaption></figure><span class="cover-doodle">✧</span></div>`:project.cover?`<div class="case-cover ${caseKey}"><figure><span class="tape"></span><img src="assets/${project.cover}.webp" alt="${project.title}作品素材"><figcaption class="handwritten">${project.category} / Sherry's notebook</figcaption></figure><span class="cover-doodle">✧</span></div>`:`<div class="script-cover"><span class="script-cloud">☁</span><span class="handwritten">允许每一种情绪</span><strong>我<br>与我<br>相处。</strong><i>DIMOO / VIDEO SCRIPT</i><span class="script-star">✧</span></div>`}<span class="screen-cue">SCROLL TO EXPLORE <b>↓</b></span></section>${project.sections.map((s,i)=>`<section class="story-section ${s.kind} section-shell" id="chapter-${i+1}"><div class="story-heading"><span class="eyebrow">${s.label}</span><h2>${s.title}</h2><span class="chapter-index">${String(i+1).padStart(2,'0')}</span></div><div class="story-body">${s.body}</div><a class="chapter-next" href="${i<project.sections.length-1?'#chapter-'+(i+2):'#next-project'}">${i<project.sections.length-1?'继续这个故事':'下一页'} ↓</a></section>`).join('')}<section class="story-section next-project section-shell" id="next-project"><span class="eyebrow">KEEP EXPLORING / 下一个故事</span><h2>${window.CASES[nextKey].title}</h2><p>${window.CASES[nextKey].subtitle}</p><div class="next-actions"><a class="primary-button" href="case.html?project=${nextKey}">继续阅读 <span>↗</span></a><a class="text-button" href="contents.html">回到目录 ☷</a></div><a href="index.html#contact" class="handwritten">也可以，聊聊你的下一个灵感 ↗</a></section>`;
 const sections=[...main.querySelectorAll(':scope > section')];
 document.querySelector('.chapter-dots').innerHTML=sections.map((s,i)=>`<a href="#${s.id}" aria-label="${i===0?'案例概览':i===sections.length-1?'下一个故事':project.sections[i-1].title}"><span>${i===0?'概览':i===sections.length-1?'继续':String(i).padStart(2,'0')}</span><i></i></a>`).join('');
 const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){document.querySelectorAll('.chapter-dots a').forEach(a=>{const active=a.hash==='#'+e.target.id;a.classList.toggle('current',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});e.target.classList.add('seen');}});},{rootMargin:'-15% 0px -45% 0px',threshold:0});sections.forEach(s=>observer.observe(s));
 let queued=false;const progress=()=>{const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.scroll-progress').style.width=(max>0?scrollY/max*100:0)+'%';queued=false;};addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(progress);}},{passive:true});progress();
 if(caseKey==='jala'){
  function selectJourney(i,focus=false){document.querySelectorAll('[data-journey]').forEach((b,n)=>{b.setAttribute('aria-selected',String(n===i));b.tabIndex=n===i?0:-1;});const j=window.JOURNEYS[i],panel=document.querySelector('#journey-panel');panel.setAttribute('aria-labelledby','journey-'+i);panel.innerHTML=`<div class="journey-title"><span>LEVEL 0${i+1}</span><h3>${j.title}</h3><p>${j.format} <b> / </b> ${j.channel}</p></div><div class="journey-content"><dl><div><dt>活动目的</dt><dd>${j.purpose}</dd></div><div><dt>内容设计</dt><dd>${j.action}</dd></div><div><dt>品牌连接</dt><dd>${j.connection}</dd></div></dl>${j.note?`<small>${j.note}</small>`:''}</div>`;if(focus)document.querySelector(`[data-journey="${i}"]`).focus();}
  selectJourney(0);document.querySelector('.journey-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-journey]');if(b)selectJourney(Number(b.dataset.journey));});document.querySelector('.journey-tabs').addEventListener('keydown',e=>{const b=e.target.closest('[data-journey]');if(!b||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const i=Number(b.dataset.journey);selectJourney(e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:3))%4,true);});
 }
}
const artDialog=document.querySelector('#art-dialog');let lastArt;
document.addEventListener('click',e=>{const b=e.target.closest('[data-zoom]');if(!b)return;lastArt=b;document.querySelector('#large-art').src=b.dataset.zoom;document.querySelector('#large-art').alt=b.querySelector('img').alt;artDialog.showModal();document.body.classList.add('modal-open');artDialog.scrollTop=0;});
document.querySelector('#close-art').addEventListener('click',()=>artDialog.close());artDialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');lastArt?.focus({preventScroll:true});});artDialog.addEventListener('click',e=>{if(e.target===artDialog){const r=artDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)artDialog.close();}});
